// v32: run packs are bought and resolved in-place, independently of permanent base packs.
const RUN_PACKS=[
 {id:'attack',name:'攻撃パック',type:'攻撃',price:40,icon:'⚔',desc:'攻撃カードが出やすい。'},
 {id:'defense',name:'防御パック',type:'防御',price:40,icon:'▱',desc:'防御カードが出やすい。'},
 {id:'support',name:'補助パック',type:'補助',price:40,icon:'⌘',desc:'補助カードが出やすい。'},
 {id:'special',name:'特殊パック',type:'特殊',price:40,icon:'✧',desc:'特殊カードが出やすい。'},
 {id:'epic',name:'エピックパック',price:60,icon:'✦',desc:'エピックカードが出やすい。エピック確定ではありません。'}
];
function getRunPacks(r){return RUN_PACKS;}
function runPackWeight(c,pack){return pack.type&&cardCategories(c).includes(pack.type)?4:1;}

function packMatches(c,axis){let f=c.fx;return axis==='筋力'?!!(c.axis==='筋力'||f.s||f.doubleStr||f.strScale||f.strengthBlock||f.exhaustStrength||f.forge):axis==='毒'?!!(c.axis==='毒'||f.p||f.equalPoison||f.totalPoison||f.poisonDouble):axis==='ブロック'?!!(c.axis==='ブロック'||f.b||f.plate||f.blockScale||f.exactBlock||f.retainBlock||f.thorns||f.thornGarden||f.thornShield||f.rage||f.burn):axis==='除外'?!!(c.axis==='除外'||f.sacrifice||f.chooseExhaust||f.exScale||f.exhaustBlock||f.engine||f.exhaustStrength||f.recoverExcluded||f.tokenSword||f.tokenKnife||f.copyDiscard):axis==='自傷'?!!(c.axis==='HP喪失'||f.hpLoss||f.revengeDamage||f.passion):false}
function runPackPool(r){return C.filter(c=>allowedRunCard(c,r)&&runCopies(r,c.id)<3)}
function rollShopPack(r,pack){let remaining=runPackPool(r),out=[];if(remaining.length<5)return out;for(let i=0;i<5;i++){
 let epic=hasRelic('energy_epic',r)?0:pack.id==='epic'?.5:.1,roll=Math.random(),rarity=roll<epic?'epic':roll<epic+.35?'rare':'common',pool=remaining.filter(c=>c.rarity===rarity);if(!pool.length)pool=remaining;
 let weight=c=>runPackWeight(c,pack),x=Math.random()*pool.reduce((n,c)=>n+weight(c),0),choice=pool.at(-1);for(let c of pool){x-=weight(c);if(x<0){choice=c;break}}out.push(choice.id);remaining=remaining.filter(c=>c.id!==choice.id)
 }return out}
function migrateShopPacks(r){let s=r.shop;if(!s)return;const old=s.packs||[],legacy={attack:'strength',defense:'poison',support:'block',special:'exhaust'};s.packs=getRunPacks(r).map(p=>{const x=old.find(x=>x.id===p.id||x.id===legacy[p.id]),purchased=x?.purchased??(x?.sold?1:0);return {id:p.id,purchased,sold:purchased>=(p.id==='epic'?1:2)};});s.cards=[];s.potions??=[]}
const buildShop32=buildShop;buildShop=function(r){let shop=buildShop32(r);shop.cards=[];shop.packs=getRunPacks(r).map(p=>({id:p.id,purchased:0,sold:false}));return shop};
function canBuyRunPack(r,p){return r&&page==='shop'&&r.mode==='shop'&&!busy&&!r.shop.packChoice&&!p.sold&&r.gold>=getRunPacks(r).find(x=>x.id===p.id).price&&runPackPool(r).length>=5&&!(p.id==='epic'&&hasRelic('energy_epic',r))}
function buyRunPack(index){let r=S.run,p=r?.shop?.packs[index];if(!p||!canBuyRunPack(r,p))return;let def=getRunPacks(r).find(x=>x.id===p.id),ids=rollShopPack(r,def);if(ids.length!==5)return;r.gold-=def.price;p.purchased=(p.purchased??(p.sold?1:0))+1;p.sold=p.purchased>=(p.id==='epic'?1:2);r.shop.packChoice={packId:p.id,ids,selected:[]};save();render()}
function togglePackCard(i){let r=S.run,p=r?.shop?.packChoice;if(page!=='shop'||busy||!p||!Number.isInteger(i)||i<0||i>=p.ids.length)return;let pos=p.selected.indexOf(i);if(pos>=0)p.selected.splice(pos,1);else if(p.selected.length<2&&runCopies(r,p.ids[i])<3)p.selected.push(i);else return;render()}
function finishRunPack(){let r=S.run,p=r?.shop?.packChoice;if(page!=='shop'||busy||!p)return;for(const i of p.selected){let id=p.ids[i];if(!C[id]||!allowedRunCard(C[id],r)||runCopies(r,id)>=3)return toast('選んだカードが取得上限です。選び直してください。')}for(const i of p.selected)addRunCard(r,p.ids[i]);r.shop.packChoice=null;save();render()}
function runPackSelection(r){let p=r.shop.packChoice,def=getRunPacks(r).find(x=>x.id===p.packId)||{name:'購入済みパック'};return `<section class="run-pack-selection"><div class="eyebrow">OPENED PACK</div><h2>${def.name}</h2><p>5枚から<strong>2枚まで</strong>選択。選んだカードをもう一度押すと解除できます。今回のランでのみ使用できます。</p><div class="cards run-pack-options">${p.ids.map((id,i)=>`<div class="run-choice ${p.selected.includes(i)?'chosen':''}">${card(id,`togglePackCard(${i})`,`<span class="choice-label">${p.selected.includes(i)?'✓ 選択中':runCopies(r,id)>=3?'所持上限':'選ぶ'}</span>`)}</div>`).join('')}</div><div class="toolbar"><strong>${p.selected.length} / 2枚を選択</strong><button class="primary" onclick="finishRunPack()">${p.selected.length?p.selected.length+'枚を受け取る':'すべてスキップ'}</button></div><p class="muted">購入代金は支払い済みです。スキップしても返金されません。</p></section>`}
shopHTML=function(){let r=S.run;migrateShopPacks(r);let s=r.shop;let top=`<div class="eyebrow">ASH MARKET</div><h2>灰商人のショップ</h2><div class="exchange-balance"><strong>◈ ${r.gold}</strong>${s.packChoice?'':'<button class="primary" onclick="next()">探索を続ける →</button>'}</div>`;if(s.packChoice)return top+runPackSelection(r);
 return top+`<p>攻撃・防御・補助・特殊パックはこのショップで各2個、エピックパックは1個まで購入可能。5枚から2枚まで選び、今回のランのデッキに追加できます。</p><div class="run-pack-grid">${s.packs.map((x,i)=>{let p=getRunPacks(r).find(p=>p.id===x.id),locked=p.id==='epic'&&hasRelic('energy_epic',r);return `<article class="tile run-pack ${p.id}"><div class="pack-emblem">${p.icon}</div><h3>${p.name}</h3><p>${p.desc}</p><small>5枚から最大2枚選択 · 残り ${Math.max(0,(p.id==='epic'?1:2)-(x.purchased||0))}個</small><button onclick="buyRunPack(${i})" ${canBuyRunPack(r,x)?'':'disabled'}>${x.sold?'売り切れ':locked?'遺物効果でEPIC禁止':runPackPool(r).length<5?'取得可能なカードが不足':'◈ '+p.price+' · 購入して開封'}</button></article>`}).join('')}</div><details class="pack-rules"><summary>パックの抽選について</summary><p>すべて潜在カード。同じパック内では重複しません。同種3枚所持のカードは出現しません。</p><p>タイプ別パック：1枠の基礎レアリティ比率はCOMMON 55%・RARE 35%・EPIC 10%。同じレアリティ内で対象タイプのカードに4倍の重みを付けます。複数のタイプを持つカードにも適用されます。</p><p>エピックパック：COMMON 15%・RARE 35%・EPIC 50%。候補がないレアリティでは残りの候補から抽選。戦闘報酬の未出現加算は適用・変動しません。</p></details><h3>消費アイテム <small>所持 ${r.potions?.length||0} / 2</small></h3><div class="potion-shop">${s.potions.map((x,i)=>{let p=POTIONS.find(p=>p.id===x.id);return `<article class="tile"><div class="potion-icon">${p.icon}</div><h3>${p.name}</h3><p>${p.desc}</p><button onclick="buyShopPotion(${i})" ${x.sold||r.gold<x.price||(r.potions?.length||0)>=2?'disabled':''}>${x.sold?'売り切れ':(r.potions?.length||0)>=2?'所持上限（2個）':'◈ '+x.price+' · 購入'}</button></article>`}).join('')||'<p>遺物効果により消費アイテムを購入できません。</p>'}</div>`
};
// Protect an unfinished choice even if the player visits another tab.
const next32=next;next=function(){if(S.run?.shop?.packChoice)return toast('パックの選択を確定するか、すべてスキップしてください');next32()};
buyShopCard=()=>{};
const buyPotion32=buyShopPotion;buyShopPotion=function(i){if(S.run?.shop?.packChoice)return;buyPotion32(i)};
function prepareChest(r){let c=r.chest;if(!c)return;if(!c.claimed)c.gold=100;if(c.version===2)return;c.version=2;c.selected=null;c.relicCount=c.claimed?0:Math.random()<.5?1:2;let pool=C.filter(x=>allowedRunCard(x,r)&&x.rarity==='epic'&&runCopies(r,x.id)<3);c.cards=[];if(c.card!=null&&pool.some(x=>x.id===c.card))c.cards.push(c.card);c.cards.push(...shuffle(pool.filter(x=>!c.cards.includes(x.id))).slice(0,2-c.cards.length).map(x=>x.id));delete c.card}
const choose32=choose;choose=function(type){choose32(type);let r=S.run;if(!r)return;if(r.mode==='shop'){migrateShopPacks(r);render()}if(r.mode==='chest'){prepareChest(r);render()}};
// Chest loot is extra: it does not consume the elite/boss loot budget.
addUnidentified=function(r,n){let combat=Math.max(0,(r.unidentifiedRelics||0)-(r.chestRelics||0)),amount=Math.max(0,Math.min((r.relicTarget||3)-combat,n));r.unidentifiedRelics=(r.unidentifiedRelics||0)+amount;r.lastRelicDrop=amount;return amount};
const victory32=victory;victory=function(){let r=S.run;if(r?.mode==='battle'&&!r.battleRelicGranted&&r.kind==='boss')addUnidentified(r,(r.relicTarget||3)-Math.max(0,(r.unidentifiedRelics||0)-(r.chestRelics||0)));victory32()};
function selectChestCard(i){let r=S.run,c=r?.chest;if(page!=='chest'||busy||!c||c.claimed||!Number.isInteger(i)||!c.cards[i]||runCopies(r,c.cards[i])>=3)return;c.selected=c.selected===i?null:i;render()}
chestHTML=function(){let r=S.run,c=r.chest;if(c.version!==2)prepareChest(r);return `<div class="reward"><div class="eyebrow">TREASURE CHEST</div><div class="chest-emblem">▣</div><h1>灰に眠る宝箱</h1><p>エピックカード${c.cards.length}枚から1枚まで選択。カードを選ばずスキップもできます。</p>${hasRelic('energy_epic',r)?'<p>遺物効果によりEPICカードは出現しません。</p>':''}<div class="cards chest-options">${c.cards.map((id,i)=>`<div class="run-choice ${c.selected===i?'chosen':''}">${card(id,c.claimed?'':`selectChestCard(${i})`,`<span class="choice-label">${c.selected===i?'✓ 選択中':runCopies(r,id)>=3?'所持上限':'選ぶ'}</span>`)}</div>`).join('')||'<p>取得可能なエピックカードがありません。</p>'}</div><div class="chest-extra"><strong>◈ ${c.gold}</strong><strong>✦ 未鑑定の遺物 ${c.relicCount}個</strong></div><p>カードをスキップしても、金と未鑑定の遺物は獲得します。</p><button class="primary" onclick="claimChest()">${c.claimed?'探索を続ける →':c.selected==null?'カードをスキップして報酬を受け取る →':'選んだカードと報酬を受け取る →'}</button></div>`};
claimChest=function(){let r=S.run,c=r?.chest;if(page!=='chest'||busy||!c)return;if(!c.claimed){let id=c.selected==null?null:c.cards[c.selected];if(id!=null&&!addRunCard(r,id))return toast('このカードは取得できません。選択を解除してください。');c.claimed=true;r.gold+=c.gold;r.chestRelics=(r.chestRelics||0)+c.relicCount;r.unidentifiedRelics=(r.unidentifiedRelics||0)+c.relicCount;save()}next()};
mapDescriptions.event='EPICカード2枚から1枚を選択・スキップ。金と未鑑定の遺物1〜2個を獲得。';mapDescriptions.shop='金でタイプ別の潜在カードパックや消費アイテムを購入。';
// Preserve paid legacy purchases and existing potion stock. Never re-roll a saved open pack.
if(S.run){if(S.run.shop)migrateShopPacks(S.run);if(S.run.chest)prepareChest(S.run)}
if(!globalThis.ASHBOUND_HEADLESS)render();
